<template><view class="page home"><view class="row heading"><view><view class="brand">登科喵<text>备考计划</text></view><view class="muted">科学规划 · 高效备考 · 一起上岸！</view></view><button class="plus" @click="create">＋</button></view><view v-if="error" class="card"><view class="error">{{error}}</view><button class="secondary" @click="load">重新加载</button></view><view v-else-if="loading" class="loading">正在加载你的计划…</view><template v-else><view class="countdown"><view class="hero-copy"><view v-if="plan" class="exam-name">{{plan.examName}}</view><view v-else class="exam-name">给努力一份计划</view><view v-if="plan" class="days">{{plan.remainingDays}}<text> 天</text></view><view v-else class="welcome">每天进步一点点</view><view class="date">{{plan?plan.examDate:'从今天开始，向目标出发'}}</view><text v-if="!plan" class="link" @click="create">开始备考 ›</text></view><image class="hero-cat" src="/static/dengkemiao.png" mode="aspectFit"/></view><view v-if="plan" class="card today"><view class="row"><text class="section">今日任务</text><text class="fraction">{{done}}/{{tasks.length}}</text></view><view class="progress"><view class="fill" :style="{width:(tasks.length?done*100/tasks.length:0)+'%'}"/></view><view v-if="!tasks.length" class="muted no-tasks">{{plan.remainingDays===0?'考试日已到，祝你从容发挥！':'今天暂无学习任务'}}</view><view v-for="t in tasks.slice(0,5)" :key="t.id" class="preview-task" @click="toggle(t)"><view :class="['check',t.completed?'checked':'']">{{t.completed?'✓':''}}</view><view class="task-copy">{{t.subject}} · {{t.name}}</view><text class="muted">{{t.duration}}分钟</text></view><button class="primary start" @click="tab('task')">▶ 开始学习</button></view><view v-else class="card"><view class="section">选择你的备考目标</view><view class="exam-grid"><view v-for="t in types" :key="t.code" class="exam-item" @click="create(t.code)"><view class="exam-symbol">{{t.symbol||t.name.slice(0,1)}}</view><text>{{t.name}}</text></view></view></view><view class="row minor-links"><text class="link" @click="tab('plan')">我的计划 ›</text><text class="link" @click="sharing=true">分享给同学 ↗</text></view><view v-if="localMode" class="muted local-note">本地体验 · 数据保存在当前设备</view></template><ShareSheet :visible="sharing" @close="sharing=false"/></view></template>
<script setup>
import {ref,computed} from 'vue';import {onShow,onShareAppMessage,onShareTimeline} from '@dcloudio/uni-app';import {api,current,localMode,showError} from '../../api';import ShareSheet from '../../components/ShareSheet.vue'
const plan=ref(null),tasks=ref([]),types=ref([]),loading=ref(true),error=ref(''),sharing=ref(false),busy=ref(false),done=computed(()=>tasks.value.filter(t=>t.completed).length)
async function load(){loading.value=true;error.value='';try{types.value=await api.templates();plan.value=await current();tasks.value=plan.value?await api.tasks(plan.value.id):[]}catch(e){error.value=e.message}finally{loading.value=false}}
async function toggle(t){if(busy.value)return;busy.value=true;try{await api.complete(t.id,!t.completed);t.completed=!t.completed}catch(e){showError(e)}finally{busy.value=false}}
onShow(()=>{
load()});onShareAppMessage(()=>({title:'登科喵备考计划 · 一起上岸',path:'/pages/index/index'}));onShareTimeline(()=>({title:'登科喵备考计划 · 一起上岸'}))
function tab(name){uni.switchTab({url:'/pages/'+name+'/index'})}function create(code=''){uni.navigateTo({url:'/pages/exam/create?type='+(typeof code==='string'?code:'')})}
</script>
<style scoped>.home{background:linear-gradient(180deg,#EAF9F0 0%,#F5FBF8 70%)}.heading{margin:0 0 26rpx}.brand{font-size:38rpx;line-height:1.4;font-weight:850;color:#082E22;letter-spacing:-1rpx}.brand text{color:#09A776}.heading .muted{font-size:21rpx}.plus{background:linear-gradient(135deg,#29C6A4,#079E78);color:#fff;width:62rpx;height:62rpx;padding:0;border-radius:50%;font-size:43rpx;line-height:60rpx;flex-shrink:0}.countdown{position:relative;min-height:290rpx;background:linear-gradient(110deg,#FFF,#ECFAF0);border-radius:28rpx;padding:30rpx;margin-bottom:22rpx;overflow:hidden}.hero-copy{position:relative;width:60%;z-index:1}.exam-name{font-size:33rpx;font-weight:750}.days{font-size:94rpx;line-height:1.4;font-weight:850;letter-spacing:-3rpx;color:#082B1E}.days text{font-size:30rpx;font-weight:500;letter-spacing:0}.date{font-size:24rpx;color:#294F40}.hero-cat{position:absolute;width:300rpx;height:315rpx;right:-22rpx;bottom:-25rpx}.welcome{font-size:35rpx;font-weight:750;color:#09A776;margin:25rpx 0}.countdown .link{display:block;margin-top:14rpx}.today .section{margin:0;font-size:31rpx}.fraction{font-weight:750;font-size:29rpx}.preview-task{display:flex;align-items:center;gap:14rpx;padding:13rpx 0;font-size:25rpx}.task-copy{flex:1;min-width:0;overflow:hidden;white-space:nowrap;text-overflow:ellipsis}.preview-task .muted{white-space:nowrap;font-size:21rpx}.today .progress{margin-bottom:15rpx}.start{margin-top:20rpx}.no-tasks{padding:25rpx 0}.card .section{margin-top:0}.exam-grid{display:grid;grid-template-columns:1fr 1fr;gap:18rpx}.exam-item{display:flex;align-items:center;gap:14rpx;background:#F0F9F4;border-radius:18rpx;padding:20rpx;font-size:25rpx}.exam-symbol{color:#10AA7E;font-weight:800;font-size:32rpx}.minor-links{margin:20rpx 8rpx}.local-note{text-align:center;font-size:20rpx;margin-top:22rpx}</style>
<style scoped>.home{padding-top:calc(28rpx + env(safe-area-inset-top))}.exam-name{overflow:hidden;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;word-break:break-all}</style>
<style scoped>.plus{margin:0}.start{padding:16rpx 20rpx;font-size:28rpx}</style>
<style scoped>
/* #ifdef MP-WEIXIN */
.home{padding-top:calc(112rpx + env(safe-area-inset-top))}
/* #endif */
</style>

